1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"path/filepath"
10	
11		"github.com/entireio/cli/cmd/entire/cli/interactive"
12		"github.com/entireio/cli/cmd/entire/cli/logging"
13		"github.com/entireio/cli/cmd/entire/cli/paths"
14		"github.com/entireio/cli/cmd/entire/cli/session"
15		"github.com/entireio/cli/cmd/entire/cli/settings"
16	
17		"charm.land/huh/v2"
18	)
19	
20	// globalTrackingHint is the one-line pointer printed by non-interactive
21	// enable paths when the machine-wide question has never been answered.
22	const globalTrackingHint = "To track every repo on this machine automatically, run 'entire enable --global'."
23	
24	// runEnableGlobalMode turns the user-global tracking tier on. It only writes
25	// the user settings file (preserving existing exclude lists) and never touches
26	// repo-level settings, so it works outside a git repository too.
27	func runEnableGlobalMode(ctx context.Context, w io.Writer) error {
28		us, err := settings.LoadUserSettings(ctx)
29		if err != nil {
30			return unreadableUserSettingsError(err)
31		}
32		if us.Global == nil {
33			us.Global = &settings.GlobalConfig{}
34		}
35		us.Global.Enabled = true
36		if err := settings.SaveUserSettings(ctx, us); err != nil {
37			return fmt.Errorf("saving user settings: %w", err)
38		}
39		fmt.Fprintln(w, "Global tracking enabled.")
40		fmt.Fprintln(w, "Entire now tracks agent sessions in every repo on this machine that has no repo-level setup.")
41		return nil
42	}
43	
44	// runDisableGlobalMode turns the user-global tracking tier off. The answer is
45	// durable: the file keeps global.enabled=false (rather than being removed), so
46	// the setup wizard never re-asks. Repo-level settings are not touched.
47	func runDisableGlobalMode(ctx context.Context, w io.Writer) error {
48		us, err := settings.LoadUserSettings(ctx)
49		if err != nil {
50			return unreadableUserSettingsError(err)
51		}
52		if us.Global == nil {
53			us.Global = &settings.GlobalConfig{}
54		}
55		us.Global.Enabled = false
56		if err := settings.SaveUserSettings(ctx, us); err != nil {
57			return fmt.Errorf("saving user settings: %w", err)
58		}
59		fmt.Fprintln(w, "Global tracking disabled.")
60		return nil
61	}
62	
63	// unreadableUserSettingsError turns a LoadUserSettings failure into an
64	// actionable message: the strict decoder also rejects files written by a
65	// newer CLI, so name the file and both ways out.
66	func unreadableUserSettingsError(err error) error {
67		return fmt.Errorf("cannot update user settings at %s: %w; upgrade entire or remove the unknown key",
68			settings.UserSettingsPath(), err)
69	}
70	
71	// maybeAskGlobalTracking asks the one-time machine-wide tracking question
72	// during interactive setup. It never asks when the global tier is already
73	// configured (either answer), and never prompts in non-interactive contexts
74	// (--yes, no TTY) — those get the one-line hint instead. An answered prompt
75	// is persisted either way, so the question is never asked twice; a cancelled
76	// prompt saves nothing, so a later enable can ask again.
77	func maybeAskGlobalTracking(ctx context.Context, w io.Writer, opts EnableOptions) {
78		us, err := settings.LoadUserSettings(ctx)
79		if err != nil || us.Global != nil {
80			// A malformed user settings file must never be overwritten from a
81			// side prompt; a configured one must never re-ask.
82			return
83		}
84		if opts.Yes || !interactive.CanPromptInteractively() {
85			fmt.Fprintln(w, globalTrackingHint)
86			return
87		}
88		enable := false
89		form := NewAccessibleForm(
90			huh.NewGroup(
91				huh.NewConfirm().
92					Title("Also track every repo on this machine automatically?").
93					Description("Applies to repos without their own Entire setup.").
94					Affirmative("Yes").
95					Negative("No").
96					Value(&enable),
97			),
98		)
99		if err := form.Run(); err != nil {
100			// Ctrl-C stays silent (nothing saved, a later enable asks again);
101			// any other prompt failure must at least be diagnosable.
102			if !errors.Is(err, huh.ErrUserAborted) && !errors.Is(err, context.Canceled) {
103				logging.Debug(ctx, "global tracking prompt failed", "error", err)
104			}
105			return
106		}
107		us.Global = &settings.GlobalConfig{Enabled: enable}
108		if err := settings.SaveUserSettings(ctx, us); err != nil {
109			fmt.Fprintf(w, "Warning: could not save the global tracking answer: %v\n", err)
110			return
111		}
112		if enable {
113			fmt.Fprintln(w, "  ✓ Global tracking enabled")
114		}
115	}
116	
117	// printGlobalTrackingHintIfUnconfigured prints the enable --global pointer on
118	// enable paths that must never prompt (--agent), when the machine-wide
119	// question has never been answered.
120	func printGlobalTrackingHintIfUnconfigured(ctx context.Context, w io.Writer) {
121		us, err := settings.LoadUserSettings(ctx)
122		if err != nil || us.Global != nil {
123			return
124		}
125		fmt.Fprintln(w, globalTrackingHint)
126	}
127	
128	// globalRuntimeSubdirs are the runtime subtrees invisible routing places
129	// under the worktree's namespace dir (<git-common-dir>/entire/worktree/
130	// <worktree-key>) for globally tracked repos, relative to that base and to
131	// the worktree's .entire directory alike.
132	var globalRuntimeSubdirs = []string{"metadata", "logs", "tmp"}
133	
134	// maybeMigrateGlobalRuntimeData moves THIS worktree's invisible-routed
135	// runtime data (<git-common-dir>/entire/worktree/<worktree-key>/
136	// {metadata,logs,tmp}) into the worktree's .entire directory. Repo-level
137	// enable flows call it BEFORE writing .entire/settings.json: that write
138	// flips path routing to the worktree, which would otherwise strand the
139	// routed files in .git. Only the current worktree's namespace is touched —
140	// sibling worktrees of the same clone keep their own namespaces (and their
141	// in-flight sessions) untouched. It triggers when the clone preferences
142	// carry the globally_enabled marker or when the routed directory is
143	// non-empty. Best-effort by contract — enable never aborts on migration
144	// failure; files that could not be moved stay in place for a later retry and
145	// the outcome is summarized in one line.
146	func maybeMigrateGlobalRuntimeData(ctx context.Context, w io.Writer) {
147		root, err := paths.WorktreeRoot(ctx)
148		if err != nil {
149			return
150		}
151		commonDir, err := session.GetGitCommonDir(ctx)
152		if err != nil {
153			return
154		}
155		// session.GetGitCommonDir can return a cwd-relative path (e.g. ".git").
156		commonDir, err = filepath.Abs(commonDir)
157		if err != nil {
158			return
159		}
160		source, err := paths.InvisibleRuntimeDir(commonDir, root)
161		if err != nil {
162			return
163		}
164	
165		triggered := false
166		if prefs, prefsErr := settings.LoadClonePreferences(ctx); prefsErr == nil && prefs.GloballyEnabled {
167			triggered = true
168		}
169		if !triggered {
170			entries, readErr := os.ReadDir(source)
171			if readErr != nil || len(entries) == 0 {
172				return
173			}
174		}
175	
176		var moved, skipped, failed int
177		for _, sub := range globalRuntimeSubdirs {
178			m, s, f := moveDirContents(filepath.Join(source, sub), filepath.Join(root, paths.EntireDir, sub))
179			moved += m
180			skipped += s
181			failed += f
182		}
183		removeEmptyDirTree(source)
184		// The parent (<git-common-dir>/entire/worktree) is shared with sibling
185		// worktrees' namespaces; os.Remove only succeeds once the last namespace
186		// is gone, which is exactly the desired cleanup.
187		_ = os.Remove(filepath.Dir(source))
188	
189		if moved+skipped+failed == 0 {
190			return
191		}
192		// ✓ elsewhere in the enable output means unqualified success, so drop it
193		// when anything failed, and name the source so leftovers are findable.
194		prefix := "  ✓ "
195		if failed > 0 {
196			prefix = "  "
197		}
198		line := fmt.Sprintf("%sMoved %d globally-tracked session file(s) into .entire/", prefix, moved)
199		if skipped > 0 {
200			line += fmt.Sprintf(", %d already present", skipped)
201		}
202		if failed > 0 {
203			line += fmt.Sprintf(", %d could not be moved (left in %s)", failed, source)
204		}
205		fmt.Fprintln(w, line)
206	}
207	
208	// migrateRenameFile is the rename used by moveDirContents; a seam so tests
209	// can force the cross-device (EXDEV) fallback deterministically.
210	var migrateRenameFile = os.Rename
211	
212	// moveDirContents moves every file under src into the same relative location
213	// under dst, creating directories as needed. Files already present in dst are
214	// skipped (left in src). Returns moved/skipped/failed counts; a missing src is
215	// (0, 0, 0).
216	func moveDirContents(src, dst string) (moved, skipped, failed int) {
217		entries, err := os.ReadDir(src)
218		if err != nil {
219			return 0, 0, 0
220		}
221		for _, entry := range entries {
222			srcPath := filepath.Join(src, entry.Name())
223			dstPath := filepath.Join(dst, entry.Name())
224			if entry.IsDir() {
225				m, s, f := moveDirContents(srcPath, dstPath)
226				moved, skipped, failed = moved+m, skipped+s, failed+f
227				continue
228			}
229			if _, statErr := os.Lstat(dstPath); statErr == nil {
230				skipped++
231				continue
232			}
233			//nolint:gosec // G301: runtime-data dirs match the .entire directory permissions
234			if mkErr := os.MkdirAll(dst, 0o755); mkErr != nil {
235				failed++
236				continue
237			}
238			if renameErr := migrateRenameFile(srcPath, dstPath); renameErr != nil {
239				// Rename fails with EXDEV when the git common dir and the
240				// worktree live on different filesystems (--separate-git-dir,
241				// linked worktree on another volume); fall back to copy+remove.
242				if copyErr := copyFileThenRemove(srcPath, dstPath); copyErr != nil {
243					failed++
244					continue
245				}
246			}
247			moved++
248		}
249		return moved, skipped, failed
250	}
251	
252	// copyFileThenRemove copies src to dst (temp file in dst's directory, then
253	// rename, so a partial copy is never left at dst) and removes src on success.
254	// Only regular files are copied; anything else stays behind as failed.
255	func copyFileThenRemove(src, dst string) error {
256		info, err := os.Lstat(src)
257		if err != nil {
258			return fmt.Errorf("stat source: %w", err)
259		}
260		if !info.Mode().IsRegular() {
261			return fmt.Errorf("not a regular file: %s", src)
262		}
263		in, err := os.Open(src) //nolint:gosec // path is derived from the git common dir, not user input
264		if err != nil {
265			return fmt.Errorf("open source: %w", err)
266		}
267		defer in.Close()
268		tmp, err := os.CreateTemp(filepath.Dir(dst), filepath.Base(dst)+".tmp-*")
269		if err != nil {
270			return fmt.Errorf("create temp: %w", err)
271		}
272		tmpName := tmp.Name()
273		removeTmp := true
274		defer func() {
275			if removeTmp {
276				_ = os.Remove(tmpName)
277			}
278		}()
279		if _, err := io.Copy(tmp, in); err != nil {
280			_ = tmp.Close()
281			return fmt.Errorf("copy contents: %w", err)
282		}
283		if err := tmp.Chmod(info.Mode().Perm()); err != nil {
284			_ = tmp.Close()
285			return fmt.Errorf("chmod temp: %w", err)
286		}
287		if err := tmp.Close(); err != nil {
288			return fmt.Errorf("close temp: %w", err)
289		}
290		if err := os.Rename(tmpName, dst); err != nil {
291			return fmt.Errorf("rename into place: %w", err)
292		}
293		removeTmp = false
294		if err := os.Remove(src); err != nil {
295			return fmt.Errorf("remove source: %w", err)
296		}
297		return nil
298	}
299	
300	// removeEmptyDirTree removes the now-empty directories left behind by
301	// moveDirContents, deepest first, including root itself. Non-empty
302	// directories (skipped or failed files) are left in place.
303	func removeEmptyDirTree(root string) {
304		entries, err := os.ReadDir(root)
305		if err != nil {
306			return
307		}
308		for _, entry := range entries {
309			if entry.IsDir() {
310				removeEmptyDirTree(filepath.Join(root, entry.Name()))
311			}
312		}
313		// os.Remove fails on non-empty directories, which is exactly the
314		// keep-what-couldn't-move behavior wanted here.
315		if err := os.Remove(root); err != nil {
316			return
317		}
